import React from 'react';
import Icon from '../../../components/AppIcon';

const VerificationProcess = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-20 md:py-28 bg-[var(--color-background)] transition-colors duration-500">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-16 md:mb-24">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-emerald-100 dark:bg-emerald-900/20 rounded-full mb-6 text-emerald-700 dark:text-emerald-400 border border-emerald-200 dark:border-emerald-800/20">
            <Icon name="CheckCircle2" size={20} />
            <span className="text-xs md:text-sm font-bold uppercase tracking-widest">Verification Process</span>
          </div>
          <h2 className="text-3xl md:text-4xl lg:text-5xl font-black text-slate-900 dark:text-white mb-6 tracking-tight italic">
            {data.title}
          </h2>
          <p className="text-base md:text-lg lg:text-xl text-slate-600 dark:text-slate-400 max-w-3xl mx-auto font-medium leading-relaxed">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 md:gap-10">
          {data.steps?.map((item, index) => (
            <div key={index} className="relative bg-white/70 dark:bg-white/5 backdrop-blur-xl rounded-2xl p-8 md:p-10 shadow-xl dark:shadow-none border border-white dark:border-white/10 hover:-translate-y-2 transition-all duration-500 group overflow-hidden">
              <div className="absolute top-0 right-0 text-7xl md:text-8xl font-black text-slate-900/5 dark:text-white/5 group-hover:text-emerald-500/10 transition-colors leading-none -mr-4 -mt-4">
                {item?.step}
              </div>

              <div className="relative">
                <div className="w-14 h-14 md:w-16 md:h-16 rounded-2xl bg-emerald-600 flex items-center justify-center mb-8 shadow-lg shadow-emerald-500/20 group-hover:scale-110 transition-transform duration-500">
                  <Icon name={item?.icon} size={32} className="text-white" />
                </div>

                <h3 className="text-xl md:text-2xl font-black text-slate-900 dark:text-white mb-4 italic leading-tight">
                  {item?.title}
                </h3>

                <p className="text-sm md:text-base text-slate-600 dark:text-slate-400 font-medium leading-relaxed">
                  {item?.description}
                </p>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-16 md:mt-24 bg-white/70 dark:bg-white/5 backdrop-blur-xl rounded-[2rem] p-8 md:p-12 shadow-xl dark:shadow-none border border-white dark:border-white/10 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 rounded-full -ml-32 -mt-32 blur-3xl"></div>

          <div className="flex flex-col lg:flex-row items-start lg:items-center gap-8 relative z-10">
            <div className="w-20 h-20 md:w-24 md:h-24 rounded-[2rem] bg-gradient-to-br from-emerald-500 to-green-600 flex items-center justify-center flex-shrink-0 shadow-xl shadow-emerald-500/20">
              <Icon name="BadgeCheck" size={48} className="text-white" />
            </div>
            <div className="flex-1">
              <h3 className="text-2xl md:text-3xl font-black text-slate-900 dark:text-white mb-4 tracking-tight italic">
                {data.badgeTitle}
              </h3>
              <p className="text-base md:text-lg text-slate-600 dark:text-slate-400 font-medium leading-relaxed">
                {data.badgeDescription}
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default VerificationProcess;