import React from 'react';
import Image from '../../../components/AppImage';
import Icon from '../../../components/AppIcon';

const TeamSection = ({ data }) => {
  if (!data) return null;

  return (
    <section className="py-20 md:py-28 bg-[var(--color-background)] transition-colors duration-500">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-16 md:mb-24">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-secondary/10 dark:bg-secondary/20 rounded-full mb-6 text-secondary border border-secondary/10">
            <Icon name="Users" size={20} />
            <span className="text-xs md:text-sm font-bold uppercase tracking-widest">Our Team</span>
          </div>
          <h2 className="text-3xl md:text-4xl lg:text-5xl font-black text-slate-900 dark:text-white mb-6 tracking-tight italic">
            {data.title}
          </h2>
          <p className="text-base md:text-lg lg:text-xl text-slate-600 dark:text-slate-400 max-w-3xl mx-auto font-medium leading-relaxed">
            {data.description}
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 md:gap-10">
          {data.members?.map((member, index) => (
            <div key={index} className="bg-white/70 dark:bg-white/5 backdrop-blur-xl rounded-3xl overflow-hidden shadow-xl dark:shadow-none border border-white dark:border-white/10 hover:-translate-y-2 transition-all duration-500 group">
              <div className="relative h-72 md:h-80 overflow-hidden">
                <Image
                  src={member?.image}
                  alt={member?.imageAlt || member?.name}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent opacity-80 group-hover:opacity-60 transition-opacity"></div>
                <div className="absolute bottom-6 left-6 right-6">
                  <h3 className="text-xl md:text-2xl font-black text-white mb-2 leading-tight italic">
                    {member?.name}
                  </h3>
                  <div className="text-sm font-bold text-secondary uppercase tracking-widest">{member?.role}</div>
                </div>
              </div>

              <div className="p-8">
                <p className="text-sm md:text-base text-slate-600 dark:text-slate-400 leading-relaxed mb-6 font-medium line-clamp-3">
                  {member?.bio}
                </p>

                <div className="flex items-center gap-4">
                  <a href={member?.linkedin} className="w-12 h-12 rounded-xl bg-slate-100 dark:bg-white/5 flex items-center justify-center text-slate-400 dark:text-slate-500 hover:bg-primary hover:text-white dark:hover:bg-primary dark:hover:text-white transition-all transform hover:scale-110 active:scale-95 shadow-sm">
                    <Icon name="Linkedin" size={20} />
                  </a>
                  <a href={member?.twitter} className="w-12 h-12 rounded-xl bg-slate-100 dark:bg-white/5 flex items-center justify-center text-slate-400 dark:text-slate-500 hover:bg-primary hover:text-white dark:hover:bg-primary dark:hover:text-white transition-all transform hover:scale-110 active:scale-95 shadow-sm">
                    <Icon name="Twitter" size={20} />
                  </a>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default TeamSection;